# ---------------------------------------------------------------- 页面 → 索引行

def _iso4(journal):
    try:
        import lit_fetch
        return lit_fetch.journal_iso4(journal or "")
    except Exception:                                          # noqa: BLE001
        return (journal or "").strip() or "NA"


def _surname(authors):
    if not authors:
        return ""
    a = authors[0] if isinstance(authors, list) else str(authors)
    a = re.sub(r"[*,†\d]+$", "", str(a)).strip()
    parts = [p for p in re.split(r"\s+", a) if p]
    return parts[-1] if parts else ""


def _zh_short(fm, base):
    """别名里的中文短标题（既有 index 行的习惯写法）。没有就返回空串。"""
    al = fm.get("aliases")
    if isinstance(al, str):
        al = [al]
    for a in (al or []):
        s = str(a).strip()
        if re.search(r"[\u4e00-\u9fff]", s) and len(s) <= 40:
            return s
    # 退路：从文件名里剥掉年份前缀与刊名后缀
    s = re.sub(r"^\d{4}-", "", base or "")
    s = re.sub(r"-[A-Za-z]+$", "", s)
    return s if re.search(r"[\u4e00-\u9fff]", s) else ""


def _resolve_path(p):
    """库根相对或绝对路径 → 绝对路径（正/反斜杠都收）。"""
    s = str(p or "").strip().strip('"').replace("\\", "/")
    if not s:
        return s
    return s if os.path.isabs(s) else os.path.join(K.VAULT, *s.split("/"))


def norm_page_arg(p):
    """把 --pages 的入参归一成 `wiki/sources/` 下的**文件名（含 .md）**。

    兼容用户实际写法：裸页名（`2026-xxx`）、带后缀（`2026-xxx.md`）、
    带目录（`sources/2026-xxx.md` / `wiki/sources/2026-xxx.md` / 含反斜杠）。
    裸名**必须补 `.md`**，否则下游 `os.path.join(SRC_DIR, page_file)` 会去找
    不带后缀的路径而 FileNotFoundError（2026-10-14 实际踩到）。
    """
    s = str(p or "").strip().strip('"').replace("\\", "/")
    if not s:
        return s
    if not s.lower().endswith(".md"):
        s += ".md"
    return s.split("/")[-1]


def page_row(page_file, page_meta=None, indeg=None):
    """生成 index.md 的一行：| [[sources/base|姓 et al. 年 刊（中文短标题）]] | 摘要 | 入站 | 日期 |"""
    base = page_file[:-3] if page_file.lower().endswith(".md") else page_file
    txt = K.read_text(os.path.join(SRC_DIR, page_file))
    fm_raw, _ = K.split_frontmatter(txt)
    fm = K.parse_frontmatter(fm_raw)
    authors = fm.get("authors")
    if isinstance(authors, str):
        authors = [authors]
    surname = _surname(authors)
    year = str(fm.get("year") or "").strip() or (fm.get("created") or "")[:4]
    journal = _iso4(fm.get("journal"))
    zh = _zh_short(fm, base)
    if surname:
        label = f"{surname} et al. {year} {journal}".strip()
        if zh:
            label += f"（{zh}）"
    else:
        label = base
    summary = re.sub(r"\s+", " ", str(fm.get("summary") or "")).strip()
    if len(summary) > 330:
        summary = summary[:330] + "…"
    if not summary:
        summary = "（待补摘要）"
    summary = summary.replace("|", "\\|")
    n_indeg = indeg if indeg is not None else in_degree(base)
    # 与既有 493 行保持同一种写法：别名分隔符用未转义的 `|`
    return f"| [[sources/{base}|{label}]] | {summary} | {n_indeg} | " \
           f"{datetime.date.today().isoformat()} |"


def in_degree(base):
    """入站链接数：其他页面（非 sources/）里出现 `[[sources/<base>` 的次数。

    ⚠️ 单页查询会**重扫整个 wiki**。批量插入 index 行时请改用 `build_indeg_map()`
    ——否则一批 N 页就是 N × 全库文件读取（实测 72 页 × ~200 文件 ≈ 14000 次读）。
    """
    return build_indeg_map().get(base, 0)


def build_indeg_map():
    """一次扫描算出全部 source 页的入站数 `{basename: count}`。

    🔴 2026-10-10 修：`page_row()` 旧版对**每一页**调 `in_degree()`，而 `in_degree()`
    每次都要把 `wiki/{concepts,entities,topics,outputs}` 下所有文件读一遍。72 页的收尾
    就要读约 14000 个文件（其中绝大多数毫无关系）。现在整批只扫一趟。
    """
    m = {}
    for d in ("concepts", "entities", "topics", "outputs"):
        p = os.path.join(K.VAULT, "wiki", d)
        if not os.path.isdir(p):
            continue
        for fn in os.listdir(p):
            if not fn.lower().endswith(".md"):
                continue
            try:
                txt = K.read_text(os.path.join(p, fn))
            except OSError:
                continue
            for mm in re.finditer(r"\[\[sources/([^\]\|#\\\n]+)", txt):
                base = mm.group(1).strip().rstrip("/\\").replace("\\", "/")
                base = base.split("/")[-1]
                if base.endswith(".md"):
                    base = base[:-3]
                m[base] = m.get(base, 0) + 1
    return m


def recent_pages(since=None, days=1, limit=0):
    if not os.path.isdir(SRC_DIR):
        return []
    cutoff = None
    if since:
        cutoff = datetime.datetime.combine(
            datetime.datetime.strptime(since, "%Y-%m-%d").date(), datetime.time.min).timestamp()
    else:
        cutoff = time.time() - days * 86400
    out = []
    for fn in sorted(os.listdir(SRC_DIR)):
        if not fn.lower().endswith(".md"):
            continue
        p = os.path.join(SRC_DIR, fn)
        if os.path.getmtime(p) >= cutoff:
            out.append(fn)
    return out[:limit] if limit else out


# ---------------------------------------------------------------- index.md 写入

def index_existing_bases(text):
    return {m.group(1) for m in (ROW_RE.match(ln) for ln in text.split("\n")) if m}


def insert_rows(text, rows):
    """把行插到 Sources 表的最后一行之后（比"footer 锚点"更稳，锚点缺失也不丢数据）。"""
    lines = text.split("\n")
    last = None
    for i, ln in enumerate(lines):
        if ROW_RE.match(ln):
            last = i
    if last is not None:
        new = lines[:last + 1] + rows + lines[last + 1:]
        return "\n".join(new), f"插在 Sources 表第 {last + 1} 行之后"
    # 退路：找 Sources 标题 + 表头 + 分隔行
    for i, ln in enumerate(lines):
        if ln.strip().startswith("## ") and "Sources" in ln:
            j = i
            while j < len(lines) and not lines[j].strip().startswith("|"):
                j += 1
            while j < len(lines) and lines[j].strip().startswith("|"):
                j += 1
            return "\n".join(lines[:j] + rows + lines[j:]), f"插在 Sources 表尾（第 {j} 行）"
    # 最后退路：footer 之前
    for i, ln in enumerate(lines):
        if FOOTER_HINT in ln:
            # ⚠️ 旧版写 `lines[:i-1]`：footer 在第 0 行时 i-1 == -1 ⇒ `lines[:-1]`
            #    会**丢掉整个文件的最后一行**（静默数据丢失）。
            k = max(i - 1, 0)
            return "\n".join(lines[:k] + rows + lines[k:]), "插在 footer 之前"
    return text.rstrip("\n") + "\n" + "\n".join(rows) + "\n", "追加到文件末尾（未找到锚点）"


def write_index(rows, apply=False, quiet=False):
    if not os.path.exists(INDEX_MD):
        return {"ok": False, "why": f"index.md 不存在：{INDEX_MD}", "added": 0}
    text = K.read_text(INDEX_MD)
    have = index_existing_bases(text)
    new_rows = [r for r in rows if re.search(r"\[\[sources/([^\]\|\\]+)", r)
                and re.search(r"\[\[sources/([^\]\|\\]+)", r).group(1) not in have]
    if not new_rows:
        return {"ok": True, "why": "所有页面已在 index.md 中（幂等，无需写入）", "added": 0}
    if not apply:
        print("\n--- 将插入 index.md 的行（干跑）---")
        for r in new_rows:
            print(r)
        bases = []
        for r in new_rows:
            m = re.search(r"\[\[sources/([^\]\|\\]+)", r)
            if m:
                bases.append(m.group(1))
        return {"ok": True, "why": f"干跑：待插入 {len(new_rows)} 行", "added": 0,
                "pending": new_rows, "inserted": bases}
    new_text, where = insert_rows(text, new_rows)
    backup_first(INDEX_MD)          # CLAUDE.md 写盘铁律 3：批量写盘前先备份
    write_text_keep_eol(INDEX_MD, new_text)
    # 写后复算：新行必须都能读回（沿用库里的"写 N 读 N"纪律）
    back = K.read_text(INDEX_MD)
    missing = [r for r in new_rows if r not in back]
    bases = []
    for r in new_rows:
        m = re.search(r"\[\[sources/([^\]\|\\]+)", r)
        if m:
            bases.append(m.group(1))
    return {"ok": not missing, "why": f"{where}，插入 {len(new_rows)} 行"
            + (f"，复核缺失 {len(missing)}" if missing else "，写后复核通过"),
            "added": len(new_rows), "inserted": bases}


# ---------------------------------------------------------------- log_ops.md

def log_line(pages):
    titles = []
    for fn in pages[:5]:
        try:
            fm, _ = K.split_frontmatter(K.read_text(os.path.join(SRC_DIR, fn)))
            t = (K.parse_frontmatter(fm).get("summary") or fn[:-3])
        except OSError:
            t = fn[:-3]
        titles.append(str(t)[:40])
    stamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M")
    return (f"- {stamp}　lit-watch 入库 {len(pages)} 篇（{', '.join(titles)}"
            + ("…" if len(pages) > 5 else "") + "）")


def write_log_ops(pages, apply=False, quiet=False):
    line = log_line(pages)
    if os.path.exists(LOG_OPS):
        if line in K.read_text(LOG_OPS):
            return {"ok": True, "why": "该条目已存在（幂等）"}
        body = K.read_text(LOG_OPS)
    else:
        body = ("# 操作日志（log_ops）\n\n"
                "> 按 CLAUDE.md：`log.md` 已冻结为历史存档，新的操作记录写在本文件。\n"
                "> 每行一条，只追加。\n\n")
    if not apply:
        print(f"\n--- 将追加到 log_ops.md ---\n{line}")
        return {"ok": True, "why": "干跑：未写入"}
    backup_first(LOG_OPS)
    write_text_keep_eol(LOG_OPS, body.rstrip("\n") + "\n" + line + "\n")
    ok = line in K.read_text(LOG_OPS)
    return {"ok": ok, "why": "已追加并复核" if ok else "写入后复核失败"}


# ---------------------------------------------------------------- 计数漂移体检
#
# 🔴 由来（2026-10-14 诊断意见 P0-2）：本库最痛恨「静默失效的声明」，而**手写页数**
#    正是最典型的一种——CLAUDE.md 写着「724 页」时实测已 862 页，且**没有任何东西会报错**，
#    因为漂移的是一句散文。纠正办法不是「记得改」，而是**让机器每次收尾都算一遍**。
#
# 判定口径（**只报事实，不改文件**）：
#   扫描「常驻配置类文档」里形如「合计 N 页」「N 页：」的**未标注快照**声明，
#   与真实页数（meta.json 的 `count`，同一份被检索层消费的数据）比对。
#   · 带 🕐 或「快照」字样的行 = **已声明为历史快照**，不算漂移（合法用法）
#   · 数值不等 ⇒ 报「文档计数漂移」，并给出该改的文件
#   · 完全不写数字（写「以 kb_stats.py 为准」）⇒ 无声明，**不报**（这是推荐写法）

DRIFT_SCAN_DOCS = (
    "CLAUDE.md",
    "tools/_MAINTENANCE.md",
    "tools/_LIT-WATCH-NEXT.md",
    ".dsh/skills/kb-query/SKILL.md",
    "tools/_README.md",
)

# 「合计/共/总计/总 N 页」「N 页：」「N 页（」等计数声明形态。
# ⚠️ 刻意**不**去匹配一切「N 页」——正文里的「共 44 页（正文 1-44）」是**论文**页数，
#    不是本库计数；误报会让这条检查沦为噪声（本库的判据：宁可少报，不可误报）。
#    故只认两种「紧邻 页 的计数语气」：
#      ① 量词开头：合计/总计/总 N 页
#         ⚠️ **刻意不收「共」**：实测它命中的几乎全是**论文**行（`共 44 页（正文 1-44）`），
#            不是本库计数。这一条是正则探针实测出来的（见 §校验器自检纪律：夹具要含反例）。
#      ② 计数后紧跟**冒号**：`**862 页**：concepts/…`（表格里的「知识层」行）
#         —— 论文行是「共 44 页（正文 1-44）」，冒号与括号都可排除，此处只认冒号。
# 🔴 `页` 与标点之间**允许 `**`**：文档里最常见的就是 `**862 页**：` 这种加粗写法，
#    首版漏了它 ⇒ 实测「该报的没报」（夹具 ①② 同时抓出）。
_DOC_COUNT_RE = re.compile(
    r"(?:合计|总计|总)\s*\**\s*(\d{2,6})\s*\**\s*页"          # 合计 724 页
    r"|\**\s*(\d{2,6})\s*\**\s*页\s*\**\s*[:：]"             # **724 页**：/ 862 页：
)


def real_page_count():
    """真实页面数：取 meta.json 的 `count`（与检索层同一份数据，不另算一遍）。"""
    try:
        with open(K.META_PATH, encoding="utf-8") as f:
            n = json.load(f).get("count")
        return int(n) if n else None
    except Exception:                                      # noqa: BLE001
        return None


def doc_count_claims():
    """-> [(文件, 行号, 行文本, 声明值)]，只含**未声明为快照**的计数声明。"""
    out = []
    for rel in DRIFT_SCAN_DOCS:
        p = os.path.join(K.VAULT, *rel.split("/"))
        if not os.path.exists(p):
            continue
        for i, line in enumerate(K.read_text(p).split("\n"), 1):
            if "🕐" in line or "快照" in line:
                continue                      # 已声明为历史快照：合法，不报
            for m in _DOC_COUNT_RE.finditer(line):
                v = m.group(1) or m.group(2)
                try:
                    out.append((rel, i, line.strip(), int(v)))
                except (TypeError, ValueError):
                    pass
    return out


def check_count_drift(quiet=False):
    """比对文档计数声明与真实页数。

    -> (ok, detail)；ok=False 表示存在**漂移的未标注声明**（应当修文档或改用权威引用）。
    真实页数取不到（索引缺失）时返回 (True, "跳过：索引缺失")，**不误报**。
    """
    real = real_page_count()
    if not real:
        return True, "跳过：meta.json 无 count（先跑 kb_build_index.py）"
    claims = doc_count_claims()
    stale = [(f, ln, txt, v) for f, ln, txt, v in claims if v != real]
    if not quiet:
        print(f"\n=== 文档计数漂移体检（真实 {real} 页）===")
        if not claims:
            print("  [ok] 未发现未标注的快照计数声明（推荐写法：只写「以 kb_stats.py 为准」）")
        for f, ln, txt, v in claims:
            mark = "ok " if v == real else "DRIFT"
            print(f"  [{mark}] {f}:{ln}  声明 {v} 页  {txt[:80]}")
    if stale:
        if not quiet:
            print(f"  ⚠️ {len(stale)} 处文档计数已漂移：手写数字必然过期，"
                  "请改为「以 `python tools/kb_stats.py` 为准」或标注 🕐 快照。")
        return False, f"{len(stale)} 处漂移"
    return True, f"{len(claims)} 处声明均与真实值一致"


# ---------------------------------------------------------------- 收尾链路

def run_chain(pages, with_corpus=False, with_semantic=False, do_index=True, quiet=False):
    py = sys.executable
    steps = []
    if do_index:
        steps.append(("kb_build_index.py", [py, os.path.join(HERE, "kb_build_index.py")], "秒级"))
    if with_semantic:
        names = [p[:-3] for p in pages]
        steps.append(("kb_semantic_search.py --add",
                      [py, os.path.join(HERE, "kb_semantic_search.py"), "--add"] + names,
                      "增量嵌入本次新页（比重建快得多）"))
    if with_corpus:
        steps.append(("kb_corpus.py --build",
                      [py, os.path.join(HERE, "kb_corpus.py"), "--build"],
                      "重建 raw 全文分块索引（约 66s）"))
    steps.append(("kb_lint.py --quick",
                  [py, os.path.join(HERE, "kb_lint.py"), "--quick"], "本批页面红旗"))
    steps.append(("kb.py --doctor", [py, os.path.join(HERE, "kb.py"), "--doctor"], "索引新鲜度"))

    env = dict(os.environ, PYTHONIOENCODING="utf-8")
    results = []
    print("\n=== 收尾链路 ===")
    for name, cmd, why in steps:
        if not os.path.exists(cmd[1]):
            print(f"  [skip] {name}（脚本不存在）")
            results.append({"step": name, "rc": 0, "skip": True})
            continue
        t0 = time.time()
        try:
            r = subprocess.run(cmd, cwd=K.VAULT, env=env, capture_output=True, text=True,
                               encoding="utf-8", errors="replace", timeout=3600)
            rc, out = r.returncode, (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            rc, out = 124, "超时"
        tail = [ln.strip() for ln in out.splitlines() if ln.strip()][-2:]
        print(f"  [{'ok  ' if rc == 0 else 'warn'}] {name}  {time.time() - t0:.1f}s"
              f"　{why}" + (f"\n         {' / '.join(tail)[:180]}" if tail else ""))
        results.append({"step": name, "rc": rc, "secs": round(time.time() - t0, 1),
                        "tail": tail})
    failed = [r for r in results if r.get("rc")]
    if failed:
        print(f"  ⚠️ {len(failed)} 步返回非零：{', '.join(r['step'] for r in failed)}"
              "（失败不阻断，但请核对上面输出）")
    if not with_semantic or not with_corpus:
        print("  提示：语料索引（--with-corpus）与语义索引（--with-semantic）未跑，"
              "新页暂不进对应的检索面。")
    # 🆕 2026-10-14（诊断 P0-2）：文档计数漂移体检——**报告但不阻断**。
    #    为什么不作为链路步骤算 rc：它是「文档卫生」而非「本次 ingest 的正确性」，
    #    让它否掉 --apply 的退出码，会诱导人去忽略它（绿灯失效的另一种形态）。
    #    故此处只在**有漂移时**显式告警；无漂移不占版面。
    try:
        ok_drift, detail = check_count_drift(quiet=True)
        if not ok_drift:
            print(f"  ⚠️ 文档计数漂移：{detail}——手写页数已过期，请改为"
                  "「以 `python tools/kb_stats.py` 为准」或标注 🕐 快照"
                  "（明细：`python tools/lit_finish.py --count-check`）")
    except Exception as e:                       # noqa: BLE001
        print(f"  [!] 计数漂移体检异常（不阻断）：{e}")
    return results


# ---------------------------------------------------------------- 自检

def selftest():
    print("=== lit_finish --selftest ===")
    ok = fail = 0

    def chk(name, cond, extra=""):
        nonlocal ok, fail
        if cond:
            print(f"  [ok  ] {name}")
            ok += 1
        else:
            print(f"  [FAIL] {name} {extra}")
            fail += 1

    import shutil
    import tempfile
    # ⚠️ 临时目录不得落在库根（旧版写 <cwd>/_litwatch-selftest-finish）。
    tmp = ""
    for base in (tempfile.gettempdir(), os.getcwd(), HERE):
        cand = os.path.join(base, "_litwatch-selftest-finish")
        try:
            shutil.rmtree(cand, ignore_errors=True)
            os.makedirs(cand, exist_ok=True)
            with open(os.path.join(cand, ".probe"), "w", encoding="utf-8") as f:
                f.write("x")
            os.remove(os.path.join(cand, ".probe"))
            tmp = cand
            break
        except OSError:
            continue
    if not tmp:
        print("  [FAIL] 无法创建自检临时目录")
        return 1
    for d in ("wiki/sources", "wiki/concepts", "wiki/outputs"):
        os.makedirs(os.path.join(tmp, *d.split("/")), exist_ok=True)
    with open(os.path.join(tmp, "wiki/sources/2026-x-JACS.md"), "w",
              encoding="utf-8", newline="\n") as f:
        f.write("---\ncreated: 2026-10-09\ntype: source\nyear: 2026\n"
                "journal: Journal of the American Chemical Society\n"
                "authors:\n  - Guangming Chen\n  - Shun Tian\n"
                'summary: "研究了固态电解质的界面失效机制，提出一种新的界面工程策略。"\n'
                "doi: 10.1021/jacs.6c00001\n---\n正文\n")
    with open(os.path.join(tmp, "wiki/concepts/固态电解质.md"), "w",
              encoding="utf-8", newline="\n") as f:
        f.write("---\ntype: concept\n---\n见 [[sources/2026-x-JACS]] 与 [[sources/2026-x-JACS|别名]]\n")
    idx = ("# 索引\n\n## 来源 Sources\n\n"
           "| 页面 | 摘要 | 入站链接数 | 最近更新 |\n|---|---|---|---|\n"
           "| [[sources/2026-old-Nat|Old et al. 2025 Nat]] | 旧 | 0 | 2026-10-01 |\n\n"
           "---\n\n_此索引由 LLM 维护，每次 ingest 时自动更新。_\n")
    with open(os.path.join(tmp, "wiki/index.md"), "w", encoding="utf-8", newline="\n") as f:
        f.write(idx)

    g = globals()
    orig = (K.VAULT, K.WIKI, g["SRC_DIR"], g["INDEX_MD"], g["LOG_OPS"])
    try:
        K.VAULT, K.WIKI = tmp, os.path.join(tmp, "wiki")
        g["SRC_DIR"] = os.path.join(tmp, "wiki", "sources")
        g["INDEX_MD"] = os.path.join(tmp, "wiki", "index.md")
        g["LOG_OPS"] = os.path.join(tmp, "wiki", "log_ops.md")

        pages = ["2026-x-JACS.md"]
        row = page_row(pages[0])
        chk("索引行含姓+年+ISO4 刊名", "Chen et al. 2026 J. Am. Chem. Soc." in row, row)
        chk("索引行含摘要与入站数", "界面失效" in row and "| 2 |" in row, row)

        r1 = write_index([row], apply=True)
        text = K.read_text(INDEX_MD)
        chk("行插在 Sources 表末尾（旧行之后）",
            text.index("2026-old-Nat") < text.index("2026-x-JACS"), "")
        chk("footer 仍在文件末尾",
            text.rstrip().endswith("_此索引由 LLM 维护，每次 ingest 时自动更新。_"))
        chk("写后复核通过", r1["ok"] and r1["added"] == 1, json.dumps(r1, ensure_ascii=False))

        r2 = write_index([row], apply=True)
        chk("幂等：第二次不再插入", r2["added"] == 0 and "已在 index.md" in r2["why"],
            json.dumps(r2, ensure_ascii=False))

        l1 = write_log_ops(pages, apply=True)
        chk("log_ops 新建并写入条目", l1["ok"] and "入库 1 篇" in K.read_text(LOG_OPS))
        l2 = write_log_ops(pages, apply=True)
        chk("log_ops 幂等（同一条目不重复）",
            K.read_text(LOG_OPS).count("入库 1 篇") == 1 and "已存在" in l2["why"],
            l2["why"])
        chk("log_ops 表头声明 log.md 已冻结",
            "log.md` 已冻结" in K.read_text(LOG_OPS))

        # 🆕 2026-10-10 回归夹具
        # ① 入站数必须**一次扫描**得出全部页，且与逐页结果一致
        m = build_indeg_map()
        chk("build_indeg_map 一次算全库，且与逐页结果一致",
            m.get("2026-x-JACS") == 2 and in_degree("2026-x-JACS") == 2, str(m))
        # ② footer 在第 0 行时**不得丢最后一行**（旧版 lines[:i-1] ⇒ lines[:-1]）
        tiny = ["_此索引由 LLM 维护，每次 ingest 时自动更新。_", "最后一行不能丢"]
        out, where = insert_rows("\n".join(tiny), ["| [[sources/new-x|X]] | s | 0 | d |"])
        chk("footer 在第 0 行时仍保留最后一行",
            "最后一行不能丢" in out and "sources/new-x" in out, where)
        # ③ 纯 CRLF 文件写回应保持 CRLF（否则 git diff 爆成几千行噪声）
        crlf_p = os.path.join(tmp, "crlf.md")
        with open(crlf_p, "wb") as f:
            f.write("a\r\nb\r\n".encode("utf-8"))
        write_text_keep_eol(crlf_p, "a\nb\nc\n")
        chk("纯 CRLF 文件写回仍是 CRLF",
            open(crlf_p, "rb").read() == "a\r\nb\r\nc\r\n".encode("utf-8"))
        # ④ 备份确实落盘（CLAUDE.md 写盘铁律 3）
        bak = backup_first(INDEX_MD)
        chk("写盘前备份落盘到 .qc_backup_*/", bool(bak) and os.path.exists(bak), str(bak))

        # ⑤ 🆕 计数漂移体检：**正例 + 反例**都必须成立
        #    （只测「该过的过了」会漏掉「该报的没报」——CLAUDE.md §校验器自检纪律 第 3 条）
        fake_meta = os.path.join(tmp, "wiki/.index/meta.json")
        os.makedirs(os.path.dirname(fake_meta), exist_ok=True)
        with open(fake_meta, "w", encoding="utf-8") as f:
            json.dump({"count": 862}, f)
        doc = os.path.join(tmp, "CLAUDE.md")

        def _drift(text):
            with open(doc, "w", encoding="utf-8") as f:
                f.write(text)
            return check_count_drift(quiet=True)

        orig_meta = K.META_PATH
        orig_vault = K.VAULT
        try:
            K.META_PATH = fake_meta
            K.VAULT = tmp          # 让 DRIFT_SCAN_DOCS 解析到合成目录，而不是真库
            ok_d, det = _drift("知识层 **862 页**：concepts 若干\n")
            chk("计数体检：声明值与真实值一致 -> 通过", ok_d, det)
            ok_d, det = _drift("知识层 **724 页**：concepts 若干\n")
            chk("计数体检：声明值过期 -> 报漂移（反例必须报）", not ok_d, det)
            ok_d, det = _drift("知识层 **724 页**　🕐 2026-10-10 快照\n")
            chk("计数体检：标注 🕐 快照 -> 不算漂移", ok_d, det)
            ok_d, det = _drift("页数一律以 `python tools/kb_stats.py` 为准\n")
            chk("计数体检：不写死数字 -> 无声明，不报", ok_d, det)
        finally:
            K.META_PATH = orig_meta
            K.VAULT = orig_vault

        # ⑥ 项目卡模式（2026-10-23）：只写指定日志，**绝不**碰 wiki/index.md。
        #    反例含义：若把项目卡按 wiki 行写法插进 index.md，项目索引的构成/缺口表
        #    会被污染，而且卡片会被插进「跨位置索引」那张错误的表。
        import contextlib
        import io
        proj_src = os.path.join(tmp, "projects", "P", "sources")
        os.makedirs(proj_src, exist_ok=True)
        with open(os.path.join(proj_src, "2026-proj-JACS.md"), "w",
                  encoding="utf-8", newline="\n") as f:
            f.write('---\ntype: source\nsummary: "项目卡摘要"\n'
                    'authors: [A. Author]\nyear: 2026\njournal: "JACS"\n---\n# x\n')
        proj_log = os.path.join(tmp, "projects", "P", "ingest", "log_ops.md")
        os.makedirs(os.path.dirname(proj_log), exist_ok=True)
        idx_before = K.read_text(INDEX_MD)
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc6 = main(["--pages", "2026-proj-JACS", "--src-dir", proj_src,
                        "--log-ops", proj_log, "--apply", "--no-chain"])
        chk("项目模式：写出项目日志",
            rc6 == 0 and os.path.exists(proj_log)
            and "入库 1 篇" in K.read_text(proj_log), buf.getvalue()[-160:])
        chk("项目模式：不修改 wiki/index.md", K.read_text(INDEX_MD) == idx_before)
        chk("项目模式：明确说明跳过 index 行", "跳过 index" in buf.getvalue())
    finally:
        K.VAULT, K.WIKI, g["SRC_DIR"], g["INDEX_MD"], g["LOG_OPS"] = orig
        shutil.rmtree(tmp, ignore_errors=True)

    print(f"\n{'SELFTEST PASSED' if fail == 0 else 'SELFTEST FAILED'}: {ok}/{ok + fail}")
    return 0 if fail == 0 else 1


# ---------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(description="入库收尾：index.md 行 + log_ops.md + 索引重建")
    ap.add_argument("--pages", nargs="*", default=[],
                    help="指定 source 卡文件名（wiki/sources/ 下；裸名/带 .md/带目录均可）")
    ap.add_argument("--since", default="", help="按修改时间取该日期之后的卡片（YYYY-MM-DD）")
    ap.add_argument("--days", type=int, default=1, help="未给 --since 时取近 N 天（默认 1）")
    ap.add_argument("--limit", type=int, default=0)
    ap.add_argument("--src-dir", default="",
                    help="卡片目录（库根相对或绝对；默认 wiki/sources）。项目卡用 projects/<slug>/sources")
    ap.add_argument("--log-ops", default="", help="日志文件（默认 wiki/log_ops.md）")
    ap.add_argument("--apply", action="store_true", help="真正写 index.md / log_ops.md")
    ap.add_argument("--no-chain", action="store_true", help="不跑索引/校验链路")
    ap.add_argument("--no-index", action="store_true", help="不重建 BM25 索引")
    ap.add_argument("--with-corpus", action="store_true", help="额外重建全文分块索引（约 66s）")
    ap.add_argument("--with-semantic", action="store_true", help="额外增量嵌入本次新页")
    ap.add_argument("--count-check", action="store_true",
                    help="只跑文档计数漂移体检（扫描文档里的手写页数声明并比对真实值）")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args(argv)

    if args.selftest:
        return selftest()

    global SRC_DIR, LOG_OPS
    if args.src_dir:
        SRC_DIR = _resolve_path(args.src_dir)
        if not os.path.isdir(SRC_DIR):
            print(f"[!] 卡片目录不存在：{SRC_DIR}", file=sys.stderr)
            return 2
    if args.log_ops:
        LOG_OPS = _resolve_path(args.log_ops)
    project_mode = os.path.normcase(SRC_DIR) != os.path.normcase(
        os.path.join(K.VAULT, "wiki", "sources"))
    if args.count_check:
        ok, detail = check_count_drift(quiet=False)
        print(f"\n{'[ok] 无漂移' if ok else '[warn] 存在漂移'}：{detail}")
        return 0 if ok else 1

    pages = args.pages or recent_pages(args.since or None, args.days, args.limit)
    pages = [norm_page_arg(p) for p in pages]
    if not pages:
        print("没有需要收尾的页面（用 --pages 指定，或 --since/--days 放宽时间）。")
        return 0
    print(f"收尾对象：{len(pages)} 页")
    for p in pages[:10]:
        print(f"  - {p}")
    if len(pages) > 10:
        print(f"  … 另 {len(pages) - 10} 页")

    if project_mode:
        # 项目索引是手维文档（构成表/缺口表/跨位置索引），不是「一行一卡」的表；
        # 按 wiki 的行格式插入会落到错误的表里。故**不写**，并明确说明原因。
        ri = {"ok": True, "why": "项目模式：跳过 index 行（项目索引为手维结构化文档）",
              "added": 0, "inserted": []}
        print(f"\n[index.md] {ri['why']}")
    else:
        # 🔴 入站数**一次扫描**算出全部页（旧版每页重扫全 wiki：72 页 ≈ 14000 次文件读）
        indeg = build_indeg_map()
        rows = [page_row(p, indeg=indeg.get(p[:-3] if p.lower().endswith(".md") else p, 0))
                for p in pages]
        ri = write_index(rows, apply=args.apply)
        print(f"\n[index.md] {ri['why']}")
    # 只把**真正新增进 index.md 的页**写进日志：以前传的是本次扫描到的全部页
    # （--days 60 时会写"入库 503 篇"这种与事实不符的记录）。
    logged_pages = [b + ".md" for b in (ri.get("inserted") or [])] or pages
    rl = write_log_ops(logged_pages, apply=args.apply)
    print(f"[log_ops.md] {rl['why']}")
    if not args.apply:
        print("\n（干跑结束；确认后加 --apply 写入，并顺带跑索引链路）")
        return 0

    rc = 0
    if not args.no_chain:
        res = run_chain(pages, with_corpus=args.with_corpus,
                        with_semantic=args.with_semantic,
                        do_index=not args.no_index)
        rc = 1 if any(r.get("rc") for r in res) else 0
    return rc


if __name__ == "__main__":
    sys.exit(main())
